def initialize_fixed_power_resources(
    units_per_zone: int = 2,
) -> list[dict[str, Any]]:
    """初始化A、B、C三区当前可用的固定供电资源。

    输入：
        units_per_zone（int）：
            每个区域内固定供电资源的数量。论文设置为2。

    输出：
        list[dict[str, Any]]：
            当前可用的固定供电资源列表。

    异常：
        ValueError：
            资源数量小于0时抛出。
    """

    if units_per_zone < 0:
        raise ValueError("固定供电资源数量不能小于0")

    resources: list[dict[str, Any]] = []
    for zone in ("A", "B", "C"):
        if zone == "B":
            # B区资源FIX-B-POWER-02发生故障，当前不可用
            for index in range(1, units_per_zone + 1):
                if index != 2:
                    resource_id = f"FIX-{zone}-POWER-{index:02d}"
                    resources.append(
                        {
                            "resource_id": resource_id,
                            "resource_type": "供电",
                            "mobility": "固定",
                            "zone": zone,
                            "current_location_id": None,
                            "capacity": 1,
                        }
                    )
        else:
            for index in range(1, units_per_zone + 1):
                resource_id = f"FIX-{zone}-POWER-{index:02d}"
                resources.append(
                    {
                        "resource_id": resource_id,
                        "resource_type": "供电",
                        "mobility": "固定",
                        "zone": zone,
                        "current_location_id": None,
                        "capacity": 1,
                    }
                )
    return resources
